public synchronized void load(String libraryName){
  if (isIos)   return;
  libraryName=mapLibraryName(libraryName);
  if (loadedLibraries.contains(libraryName))   return;
  try {
    if (isAndroid)     System.loadLibrary(libraryName);
 else     System.load(extractFile(libraryName,null).getAbsolutePath());
  }
 catch (  Throwable ex) {
    String osName;
    try {
      osName = System.getProperty("os.name");
    } catch (SecurityException e) {
      osName = "unknown";
    }
    throw new GdxRuntimeException("Couldn't load shared library '" + libraryName + "' for target: "+ osName + (is64Bit ? ", 64-bit" : ", 32-bit"),ex);
  }
  loadedLibraries.add(libraryName);
}
